      out.write("        function pickSingleKppSubmissionStatus(actionType, ksppDecision, ujpppDecision) {\r\n");
      out.write("            var action = String(actionType || '').toUpperCase();\r\n");
      out.write("            var kspp = normalizeKsppDecision(ksppDecision);\r\n");
      out.write("            var ujppp = normalizeUjpppDecision(ujpppDecision);\r\n");
      out.write("\r\n");
      out.write("            if (action === 'KSPP') {\r\n");
      out.write("                return kspp;\r\n");
      out.write("            }\r\n");
      out.write("            if (action === 'UJPPP') {\r\n");
      out.write("                return ujppp;\r\n");
      out.write("            }\r\n");
      out.write("            if (action === 'KSPP_UJPPP') {\r\n");
      out.write("                if (ujppp.css === 'kpp-status-warn') {\r\n");
      out.write("                    return ujppp;\r\n");
      out.write("                }\r\n");
      out.write("                if (ujppp.text !== 'UJPP: -') {\r\n");
      out.write("                    return ujppp;\r\n");
      out.write("                }\r\n");
      out.write("                if (kspp.text !== 'KSPP: -') {\r\n");
      out.write("                    return kspp;\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            return { text: 'Status: -', css: 'kpp-status-neutral' };\r\n");
      out.write("        }\r\n");
