      out.write("                    icon.src = contextPath + '/assets/images/icon-unarchive.png';\r\n");
      out.write("                }\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            // For unarchive, remove row from archived view (or fallback to reload if row cannot be removed safely)\r\n");
