      out.write("        function getValue(payload, key) {\r\n");
      out.write("            if (!payload || typeof payload !== 'object') {\r\n");
      out.write("                return '';\r\n");
      out.write("            }\r\n");
      out.write("            if (!Object.prototype.hasOwnProperty.call(payload, key)) {\r\n");
      out.write("                return '';\r\n");
      out.write("            }\r\n");
      out.write("            var value = payload[key];\r\n");
      out.write("            if (value === null || value === undefined) {\r\n");
      out.write("                return '';\r\n");
      out.write("            }\r\n");
      out.write("            return String(value);\r\n");
      out.write("        }\r\n");
