      out.write("        function createFieldRow(label, value) {\r\n");
      out.write("            var row = document.createElement('div');\r\n");
      out.write("            row.className = 'kpp-modal-row';\r\n");
      out.write("            var isSyorField = String(label || '').indexOf('Syor (diterima/ditolak/digantung/dibatal)') === 0;\r\n");
      out.write("            if (isSyorField) {\r\n");
      out.write("                row.classList.add('kpp-modal-row-syor');\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            var title = document.createElement('b');\r\n");
      out.write("            title.textContent = label;\r\n");
      out.write("\r\n");
      out.write("            var content = document.createElement('span');\r\n");
      out.write("            content.textContent = value && value.trim() ? value : '-';\r\n");
      out.write("            if (isSyorField) {\r\n");
      out.write("                var normalized = (value || '').toString().trim().toLowerCase();\r\n");
      out.write("                if (normalized === 'terima' || normalized === 'diterima') {\r\n");
      out.write("                    content.classList.add('kpp-syor-accepted');\r\n");
      out.write("                } else if (normalized === 'ditolak' || normalized === 'digantung' || normalized === 'dibatal') {\r\n");
      out.write("                    content.classList.add('kpp-syor-rejected');\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            row.appendChild(title);\r\n");
      out.write("            row.appendChild(content);\r\n");
